// Shape an inbound thumbs-down into an eval INBOX record. This is NOT yet a
// dataset case: scripts/eval_capture.py --ingest promotes it (tokenizing the
// prompt via the scrubber) into eval/datasets/<name>/. A thumbs-down means the
// output was wrong, so we default to a JUDGE grader whose goal is the reviewer's
// note — the case should PASS once the fix lands. The record IS the item json so
// the downstream convertToFile serializes exactly it (no wrapper fields).
const b = ($json.body) ? $json.body : $json;   // webhook wraps payload in .body
const scope = b.scope;
if (!scope) { throw new Error('feedback: scope is required'); }
const ts = new Date();
const stamp = ts.toISOString().replace(/[:.]/g, '-');
const rand = Math.random().toString(16).slice(2, 8);
const id = `${(b.task_type || 'case')}-${stamp}-${rand}`;
const rec = {
  id,
  scope,
  task_type: b.task_type || 'generate',
  action: b.action || 'advise',
  prompt: b.prompt || '',
  output: b.output || '',
  verdict: b.verdict || 'thumbs-down',
  note: b.note || '',
  source: 'feedback-flag',
  created: ts.toISOString().slice(0, 10)
};
// Optional explicit grader passthrough (else eval_capture defaults to judge+note).
if (b.grader) { rec.grader = b.grader; }
return [{ json: rec }];
